        SaneBoundary sane=new SaneBoundary(h.cpu,currentProgram);for(int step=0;step<500000;step++){long pc=h.pc(),sp=h.sp();if(pc==stop)return;if(pc==0x400038){h.cpu.writeRegister("D0",Math.abs(h.word(sp+4)));h.ret();continue;}if(pc==0x153ca4){result.rng(h);continue;}if(pc==0x133a18||pc==0x16474a){result.sound(h);continue;}if(pc==0x13154c||pc==0x123d1c||pc==0x1107cc||pc==0x158454||pc==0x15b2f6||pc==0x1205f8||pc==0x12e4e4){h.ret();continue;}if((h.word(pc)&65535)==0xa9eb){sane.execute();continue;}if(!h.cpu.step(monitor))throw new Exception("Required firearm at "+Long.toHexString(pc)+": "+h.cpu.getLastError());}throw new Exception("Required firearm instruction budget");
